UID_RE = re.compile(r'^u[a-z0-9]{6,30}$')
UNAME_RE = re.compile(r'^[a-z0-9_.]{3,24}$')
EMAIL_RE = re.compile(r'^[^\s@<>"\'\\]{1,64}@[^\s@<>"\'\\]{1,190}\.[^\s@<>"\'\\]{2,24}$')
PHONE_RE = re.compile(r'^\+?\d{8,15}$')
IMG_RE = re.compile(r'^data:image/(jpeg|png|webp);base64,([A-Za-z0-9+/]+={0,2})$')
CTRL_RE = re.compile(r'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f\u200e\u200f\u202a-\u202e\u2066-\u2069]')
TAGS_RE = re.compile(r'[<>]')

def now_ms(): return int(time.time() * 1000)

# ----------------------------------------------------------------- config
def load_config(env=None):
    e = os.environ if env is None else env
    g = lambda k, d='': e.get('LUMI_' + k, d)
    base = g('BASE_URL').rstrip('/')
    c = dict(
        host=g('HOST', '127.0.0.1'), port=int(g('PORT', '8080') or 8080), db=g('DB', 'lumi.db'),
        base_url=base, secure=base.startswith('https://'), trust_proxy=g('TRUST_PROXY') in ('1', 'true', 'yes'),
        google_id=g('GOOGLE_CLIENT_ID'), google_secret=g('GOOGLE_CLIENT_SECRET'),
        google_auth_url=g('GOOGLE_AUTH_URL', 'https://accounts.google.com/o/oauth2/v2/auth'),
        google_token_url=g('GOOGLE_TOKEN_URL', 'https://oauth2.googleapis.com/token'),
        tg_token=g('TELEGRAM_BOT_TOKEN'), tg_api=g('TELEGRAM_API', 'https://api.telegram.org').rstrip('/'),
        tls_cert=g('TLS_CERT'), tls_key=g('TLS_KEY'), quiet=g('QUIET') == '1')
    if c['tls_cert'] and c['tls_key'] and not base:
        c['secure'] = True
    return c

# ----------------------------------------------------------------- passwords
SCRYPT_N, SCRYPT_R, SCRYPT_P = 2 ** 15, 8, 1
def _b64(b): return base64.b64encode(b).decode()
def hash_pw(pw, n=None):
    n = n or SCRYPT_N
    salt = secrets.token_bytes(16)
    h = hashlib.scrypt(pw.encode('utf-8'), salt=salt, n=n, r=SCRYPT_R, p=SCRYPT_P, maxmem=256 * 1024 * 1024, dklen=32)
    return 'scrypt$%d$%d$%d$%s$%s' % (n, SCRYPT_R, SCRYPT_P, _b64(salt), _b64(h))
DUMMY_HASH = None
def verify_pw(pw, stored):
    """constant-time; also burns equivalent time when the account does not exist (stored=None)"""
    global DUMMY_HASH
    if not stored:
        if DUMMY_HASH is None: DUMMY_HASH = hash_pw('dummy-password-1')
        stored = DUMMY_HASH; ok_possible = False
    else: ok_possible = True
    try:
        _, n, r, p, salt, h = stored.split('$')
        calc = hashlib.scrypt(pw.encode('utf-8'), salt=base64.b64decode(salt), n=int(n), r=int(r), p=int(p), maxmem=256 * 1024 * 1024, dklen=32)
        return hmac.compare_digest(calc, base64.b64decode(h)) and ok_possible
    except Exception:
        return False
def pw_ok(p):
    return isinstance(p, str) and 8 <= len(p) <= 128 and re.search(r'[A-Za-z]', p) is not None and re.search(r'\d', p) is not None
PW_MSG = 'Password: 8+ characters with a letter and a number'
def sha(s): return hashlib.sha256(s.encode() if isinstance(s, str) else s).hexdigest()
def tok(n=32): return secrets.token_urlsafe(n)
def new_uid(): return 'u' + ''.join(secrets.choice('abcdefghijklmnopqrstuvwxyz0123456789') for _ in range(10))
def new_id(): return secrets.token_hex(8)

# ----------------------------------------------------------------- sanitizing
def s_txt(v, n=200, tags=True):
    if not isinstance(v, str): return ''
    v = CTRL_RE.sub('', v).strip()
    if tags: v = TAGS_RE.sub('', v)
    return v[:n]
def to_digits(s):
    return str(s or '').translate({ord(c): str(i) for i, c in enumerate('۰۱۲۳۴۵۶۷۸۹')}).translate({ord(c): str(i) for i, c in enumerate('٠١٢٣٤٥٦٧٨٩')})
def norm_phone(v): return re.sub(r'[\s\-()]', '', to_digits(v))
VID_RE = re.compile(r'^data:video/(mp4|webm|quicktime);base64,([A-Za-z0-9+/=]+)$')
def video_ok(v, max_bytes):
    """validate a data:video URL — mime, base64, container magic and decoded size"""
    if not isinstance(v, str) or len(v) > max_bytes * 4 // 3 + 80: return False
    m = VID_RE.match(v)
    if not m: return False
    try: raw = base64.b64decode(m.group(2), validate=True)
    except Exception: return False
    if len(raw) > max_bytes or len(raw) < 12: return False
    return raw[4:8] in (b'ftyp', b'moov', b'mdat', b'free', b'wide') or raw[:4] == b'\x1a\x45\xdf\xa3'
def img_ok(v, max_bytes=700 * 1024):
    """validate a data:image URL — mime, base64, magic bytes and decoded size"""
    if not isinstance(v, str) or len(v) > max_bytes * 4 // 3 + 64: return False
    m = IMG_RE.match(v)
    if not m: return False
    try: raw = base64.b64decode(m.group(2), validate=True)
    except Exception: return False
    if len(raw) > max_bytes or len(raw) < 12: return False
    k = m.group(1)
    if k == 'jpeg': return raw[:3] == b'\xff\xd8\xff'
    if k == 'png': return raw[:8] == b'\x89PNG\r\n\x1a\n'
    return raw[:4] == b'RIFF' and raw[8:12] == b'WEBP'

# ----------------------------------------------------------------- profile helpers
MINPCT = 70
def _strs(v, n, m):
    return [s_txt(x, m) for x in (v if isinstance(v, list) else [])[:n] if isinstance(x, str) and s_txt(x, m)]
def prof_pct(p):
    """profile completeness 0-100 — same weights as the app (the SERVER decides who may like / chat)"""
    if not isinstance(p, dict): return 0
    life = p.get('life') if isinstance(p.get('life'), dict) else {}
    ph = p.get('photos') if isinstance(p.get('photos'), list) else []
    sc = 0
    sc += 20 if len(ph) > 0 else 0
    sc += 10 if len(str(p.get('bio') or '').strip()) >= 20 else 0
    sc += 10 if (p.get('prov') and p.get('cityn')) else 0
    sc += 5 if p.get('height') else 0
    sc += 5 if p.get('gender') else 0
    sc += 10 if p.get('goal') else 0
    sc += 10 if sum(1 for v in life.values() if v) >= 3 else 0
    sc += 5 if p.get('belief') else 0
    sc += 5 if len(_strs(p.get('values'), 40, 40)) >= 3 else 0
    sc += 10 if len(_strs(p.get('interests'), 40, 30)) >= 3 else 0
    sc += 5 if len(_strs(p.get('langs'), 40, 30)) >= 1 else 0
    sc += 5 if str(p.get('job') or '').strip() else 0
    return sc
def age_from_dob(d):
    try:
        y, m, dd = [int(x) for x in str(d)[:10].split('-')]
        n = time.gmtime(); a = n.tm_year - y - ((n.tm_mon, n.tm_mday) < (m, dd))
        return a if 18 <= a <= 99 else 0
    except Exception: return 0

