class DB:
    def __init__(self, path):
        self.path = path
        self.tl = threading.local()
        c = self.c()
        c.executescript(SCHEMA)
        self.migrate(c)
        if path != ':memory:':
            try: os.chmod(path, 0o600)
            except OSError: pass
    def migrate(self, c):
        """upgrade databases created by older versions (adds columns; legacy paying members become VIP)"""
        def cols(t): return {r[1] for r in c.execute('PRAGMA table_info(%s)' % t).fetchall()}
        uc = cols('users')
        if 'tier' not in uc:
            c.execute("ALTER TABLE users ADD COLUMN tier TEXT NOT NULL DEFAULT 'regular' CHECK(tier IN('regular','vip'))")
            c.execute("UPDATE users SET tier='vip' WHERE premium=1")
        if 'group_admin' not in uc: c.execute("ALTER TABLE users ADD COLUMN group_admin INTEGER NOT NULL DEFAULT 0 CHECK(group_admin IN(0,1))")
        if 'pct' not in uc:
            c.execute("ALTER TABLE users ADD COLUMN pct INTEGER NOT NULL DEFAULT 0 CHECK(pct BETWEEN 0 AND 100)")
            for r in c.execute("SELECT id,profile FROM users").fetchall():
                try: v = prof_pct(json.loads(r[1] or '{}'))
                except Exception: v = 0
                c.execute("UPDATE users SET pct=? WHERE id=?", (v, r[0]))
        if 'group_muted' not in uc: c.execute("ALTER TABLE users ADD COLUMN group_muted INTEGER NOT NULL DEFAULT 0 CHECK(group_muted IN(0,1))")
        if 'tier' not in cols('payments'):
            c.execute("ALTER TABLE payments ADD COLUMN tier TEXT NOT NULL DEFAULT 'vip' CHECK(tier IN('regular','vip'))")
    def c(self):
        cn = getattr(self.tl, 'cn', None)
        if cn is None:
            if self.path == ':memory:':
                raise RuntimeError('use a file DB')
            cn = sqlite3.connect(self.path, timeout=10, isolation_level=None, check_same_thread=True)
            cn.row_factory = sqlite3.Row
            cn.execute('PRAGMA journal_mode=WAL'); cn.execute('PRAGMA foreign_keys=ON')
            cn.execute('PRAGMA synchronous=FULL'); cn.execute('PRAGMA busy_timeout=8000'); cn.execute('PRAGMA trusted_schema=OFF')
            self.tl.cn = cn
        return cn
    def q(self, sql, a=()): return self.c().execute(sql, a).fetchall()
    def one(self, sql, a=()):
        r = self.c().execute(sql, a).fetchone(); return r
    def x(self, sql, a=()): return self.c().execute(sql, a)
    def tx(self):
        return _Tx(self.c())
class _Tx:
    def __init__(self, c): self.c = c
    def __enter__(self): self.c.execute('BEGIN IMMEDIATE'); return self.c
    def __exit__(self, t, v, tb):
        if t is None: self.c.execute('COMMIT')
        else: self.c.execute('ROLLBACK')
        return False

class ApiError(Exception):
    def __init__(self, code, msg, extra=None):
        self.code, self.msg, self.extra = code, msg, extra or {}

# ----------------------------------------------------------------- rate limiting
class Limiter:
    def __init__(self): self.d = {}; self.l = threading.Lock(); self.n = 0
    def hit(self, key, limit, window):
        """returns True if allowed (and records the hit)"""
        t = time.time()
        with self.l:
            self.n += 1
            if self.n % 500 == 0:
                for k in [k for k, v in self.d.items() if not v or v[-1] < t - 3600]: del self.d[k]
            a = [x for x in self.d.get(key, []) if x > t - window]
            if len(a) >= limit:
                self.d[key] = a; return False
            a.append(t); self.d[key] = a; return True
    def count(self, key, window):
        t = time.time()
        with self.l: return len([x for x in self.d.get(key, []) if x > t - window])
    def clear(self, key):
        with self.l: self.d.pop(key, None)

