def _int(v, lo, hi, d):
    try:
        if isinstance(v, bool): return d
        n = int(v)
        return n if lo <= n <= hi else d
    except Exception: return d
def _bool_map(o, n=40):
    r = {}
    if isinstance(o, dict):
        for k, v in list(o.items())[:n]:
            if isinstance(k, str) and len(k) <= 40 and isinstance(v, bool): r[k] = v
    return r
VIP_NUM = {'dailyLikes': (1, 1000, 10), 'freePhotos': (1, 50, 3), 'vipPhotos': (1, 50, 10), 'boostMin': (5, 1440, 60), 'boostCoolH': (1, 720, 24),
           'dmDaily': (1, 100, 5), 'videoSec': (3, 60, 15), 'videoMB': (1, 8, 4)}
VIP_PERKS = ('boost', 'wholiked', 'visitors', 'unlimited', 'dm', 'ghost', 'hideonline', 'hideloc', 'media', 'rewind', 'reads', 'stickers', 'filters', 'passport', 'video', 'theme', 'photos')
def sanitize_vip(o):
    o = o if isinstance(o, dict) else {}
    r = {k: _int(o.get(k), lo, hi, d) for k, (lo, hi, d) in VIP_NUM.items()}
    if r['vipPhotos'] < r['freePhotos']: r['vipPhotos'] = r['freePhotos']
    pk = o.get('perks') if isinstance(o.get('perks'), dict) else {}
    r['perks'] = {k: (pk.get(k) if pk.get(k) in ('vip', 'all', 'off') else 'vip') for k in VIP_PERKS}
    return r
def sanitize_site(o):
    """validate everything an admin can store as site settings; returns a clean dict"""
    if not isinstance(o, dict): raise ApiError(400, 'bad_settings')
    r = dict(DEFAULT_SITE)
    r['siteName'] = s_txt(o.get('siteName', ''), 60)
    r['contactEmail'] = s_txt(o.get('contactEmail', ''), 120)
    r['registrationOpen'] = o.get('registrationOpen') is not False
    r['maintenance'] = o.get('maintenance') is True
    r['minAge'] = _int(o.get('minAge'), 18, 99, 18)
    r['maxPhotos'] = _int(o.get('maxPhotos'), 1, 50, 20)
    r['maxMsgLen'] = _int(o.get('maxMsgLen'), 50, 5000, 500)
    r['autoFlag'] = o.get('autoFlag') is not False
    r['autoSuspendReports'] = _int(o.get('autoSuspendReports'), 1, 1000, 5)
    a = o.get('announce') if isinstance(o.get('announce'), dict) else {}
    r['announce'] = {'on': a.get('on') is True, 'text': s_txt(a.get('text', ''), 200)}
    f = o.get('features') if isinstance(o.get('features'), dict) else {}
    r['features'] = {k: v for k, v in _bool_map(f).items()}
    r['features'].setdefault('discover', True); r['features'].setdefault('chat', True); r['features'].setdefault('group', True)
    tx = {'fa': {}, 'tr': {}, 'en': {}}
    if isinstance(o.get('texts'), dict):
        for L in tx:
            t = o['texts'].get(L)
            if isinstance(t, dict):
                for k, v in list(t.items())[:60]:
                    if isinstance(k, str) and len(k) <= 80 and isinstance(v, str) and v: tx[L][s_txt(k, 80, False)] = s_txt(v, 140)
    r['texts'] = tx
    r['buttons'] = _bool_map(o.get('buttons')); r['pages'] = _bool_map(o.get('pages'))
    im = o.get('images') if isinstance(o.get('images'), dict) else {}
    r['images'] = {k: (im.get(k) if img_ok(im.get(k), 400 * 1024) else '') for k in ('mark', 'word')}
    r['accent'] = s_txt(o.get('accent', ''), 12, False) if re.match(r'^#[0-9a-fA-F]{3,8}$', str(o.get('accent', ''))) else ''
    pay = o.get('pay') if isinstance(o.get('pay'), dict) else {}
    card = re.sub(r'\D', '', to_digits(pay.get('card', '')))
    r['vip'] = sanitize_vip(o.get('vip'))
    r['pay'] = {'card': card if len(card) == 16 else '', 'owner': s_txt(pay.get('owner', ''), 40), 'bank': s_txt(pay.get('bank', ''), 40)}
    r['plansInit'] = o.get('plansInit') is True
    pl = []
    seen = set()
    if isinstance(o.get('plans'), list):
        for p in o['plans'][:12]:
            if not isinstance(p, dict): continue
            pid = str(p.get('id', ''))
            if not re.match(r'^[A-Za-z0-9_-]{1,30}$', pid) or pid in seen: continue
            price = re.sub(r'[,\s\u066c\u060c]', '', to_digits(p.get('price', '')))
            if not re.match(r'^\d{1,10}$', price) or not (0 < int(price) <= 10 ** 9): continue
            per = p.get('period') if p.get('period') in PERDAYS else 'ماهانه'
            feats = '\n'.join([s_txt(x, 80) for x in str(p.get('features', '')).split('\n') if s_txt(x, 80)][:10])
            pl.append({'id': pid, 'name': s_txt(p.get('name', ''), 40) or 'Premium', 'price': str(int(price)), 'period': per, 'features': feats, 'on': p.get('on') is True, 'tier': 'vip' if p.get('tier') == 'vip' else 'regular'})
            seen.add(pid)
    if r['plansInit'] and pl and not any(p['tier'] == 'vip' for p in pl):      # older settings: derive the VIP plans from the regular ones
        for p in [x for x in pl if x['tier'] == 'regular'][:6]:
            vid = ('v' + p['id'])[:30]
            if vid not in seen and len(pl) < 12:
                pl.append({'id': vid, 'name': p['name'], 'price': p['price'], 'period': p['period'], 'features': PL_FVIP, 'on': p['on'], 'tier': 'vip'}); seen.add(vid)
    for p in pl:                                  # a VIP plan ALWAYS costs exactly 2x the regular plan of the same period
        if p['tier'] == 'vip':
            b = next((x for x in pl if x['tier'] == 'regular' and x['period'] == p['period']), None)
            if b: p['price'] = str(min(int(b['price']) * 2, 10 ** 9))
    r['plans'] = pl
    r['blockedWords'] = [s_txt(w, 40) for w in (o.get('blockedWords') if isinstance(o.get('blockedWords'), list) else [])[:200] if isinstance(w, str) and s_txt(w, 40)]
    return r

# ----------------------------------------------------------------- app
class Ctx:
    pass

LOGIN_OK_NOCSRF = {'/api/signup', '/api/login', '/api/admin/login', '/api/visit', '/api/auth/google/start', '/api/auth/telegram/start', '/api/auth/telegram/poll', '/api/support/guest'}

class App:
    def __init__(self, cfg):
        self.cfg = cfg
        self.db = DB(cfg['db'])
        self.lim = Limiter()
        self.tg_user = ''
        self.stop = threading.Event()
        self.routes = {}
        self._reg()
        self._ui = None
        self.site_cache = None

    # ---- settings
    def site(self):
        r = self.db.one("SELECT value FROM settings WHERE key='site'")
        if r:
            try: return sanitize_site(json.loads(r['value']))
            except Exception: pass
        return dict(DEFAULT_SITE)
    def save_site(self, o):
        s = sanitize_site(o)
        self.db.x("INSERT INTO settings(key,value) VALUES('site',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (json.dumps(s, ensure_ascii=False),))
        return s
    def plans(self):
        s = self.site()
        src = s['plans'] if s['plansInit'] else [dict(p) for p in DEFAULT_PLANS]
        out = []
        for p in src:
            if p.get('on') is True: out.append(p)
        return out
    def plan(self, pid):
        for p in self.plans():
            if p['id'] == pid: return p
        return None
    def public_site(self):
        s = self.site()
        d = {k: s[k] for k in PUBLIC_KEYS}
        d['plans'] = self.plans() if True else []
        d['plansInit'] = True          # plans list already resolved (defaults included)
        return d

    # ---- sessions
    def new_session(self, ctx, uid):
        t = tok(); csrf = tok(24); n = now_ms()
        self.db.x("INSERT INTO sessions(id,user_id,csrf,created,last_seen,expires) VALUES(?,?,?,?,?,?)", (sha(t), uid, csrf, n, n, n + 30 * DAY))
        ctx.cookies.append(self.cookie('s', t, 30 * 86400))
        ctx.new_csrf = csrf
        return csrf
    def cookie(self, kind, val, maxage):
        name = ('__Host-' if self.cfg['secure'] else '') + {'s': 'lumi_s', 'a': 'lumi_a', 'o': 'lumi_o'}[kind]
        c = '%s=%s; Path=/; HttpOnly; SameSite=%s; Max-Age=%d' % (name, val, 'Lax' if kind == 'o' else 'Strict' if kind == 'a' else 'Lax', maxage)
        if self.cfg['secure']: c += '; Secure'
        return c
    def read_cookie(self, ctx, kind):
        name = ('__Host-' if self.cfg['secure'] else '') + {'s': 'lumi_s', 'a': 'lumi_a', 'o': 'lumi_o'}[kind]
        for part in ctx.headers.get('Cookie', '').split(';'):
            k, _, v = part.strip().partition('=')
            if k == name and re.match(r'^[A-Za-z0-9_\-]{20,80}$', v): return v
        return None
    def load_session(self, ctx):
        ctx.user = None; ctx.session = None; ctx.admin = None; ctx.asession = None
        t = self.read_cookie(ctx, 's'); n = now_ms()
        if t:
            r = self.db.one("SELECT s.id sid,s.csrf,s.last_seen,s.expires,u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.id=?", (sha(t),))
            if r and r['expires'] > n and r['last_seen'] > n - 7 * DAY and r['status'] == 'active' and not r['deleted']:
                ctx.user = r; ctx.session = {'id': r['sid'], 'csrf': r['csrf']}
                if n - r['last_seen'] > 300000: self.db.x("UPDATE sessions SET last_seen=? WHERE id=?", (n, r['sid']))
            elif r: self.db.x("DELETE FROM sessions WHERE id=?", (r['sid'],))
        a = self.read_cookie(ctx, 'a')
        if a:
            r = self.db.one("SELECT s.id sid,s.csrf,s.last_seen,s.expires,ad.id aid,ad.username FROM admin_sessions s JOIN admins ad ON ad.id=s.admin_id WHERE s.id=?", (sha(a),))
            if r and r['expires'] > n and r['last_seen'] > n - 2 * 3600000:
                ctx.admin = r; ctx.asession = {'id': r['sid'], 'csrf': r['csrf']}
                if n - r['last_seen'] > 60000: self.db.x("UPDATE admin_sessions SET last_seen=? WHERE id=?", (n, r['sid']))
            elif r: self.db.x("DELETE FROM admin_sessions WHERE id=?", (r['sid'],))
        if random_purge():
            self.db.x("DELETE FROM sessions WHERE expires<?", (n,)); self.db.x("DELETE FROM admin_sessions WHERE expires<?", (n,))
            self.db.x("DELETE FROM oauth_states WHERE expires<?", (n,)); self.db.x("DELETE FROM tg_logins WHERE expires<?", (n,))

    # ---- views
    def providers_of(self, uid):
        return {r['provider']: r['display'] for r in self.db.q("SELECT provider,display FROM identities WHERE user_id=?", (uid,))}
    def is_vip(self, u):
        if not u['premium'] or u['tier'] == 'regular': return False
        pu = u['premium_until'] or 0
        return pu == 0 or pu > int(time.time() * 1000)

    def user_view(self, u):
        pv = self.providers_of(u['id'])
        return {'id': u['id'], 'username': u['username'], 'name': u['name'], 'email': u['email'] or '', 'phone': u['phone'] or '', 'age': u['age'],
                'gender': u['gender'], 'city': u['city'], 'bio': u['bio'], 'interests': json.loads(u['interests'] or '[]'), 'status': u['status'],
                'createdAt': u['created_at'], 'trialUntil': u['trial_until'], 'premium': bool(u['premium']), 'vip': self.is_vip(u), 'tier': u['tier'], 'groupAdmin': bool(u['group_admin']), 'groupMuted': bool(u['group_muted']), 'premiumUntil': u['premium_until'],
                'must': bool(u['must_change']), 'hasPw': bool(u['pw_hash']), 'providers': pv, 'profile': json.loads(u['profile'] or '{}')}
    def ip(self, ctx): return ctx.ip

    def audit(self, ctx, actor, action, target=''):
        self.db.x("INSERT INTO audit(t,actor,action,target,ip) VALUES(?,?,?,?,?)", (now_ms(), actor, action[:60], str(target)[:80], ctx.ip))
    def log(self, uid, text, kind='info'):
        self.db.x("INSERT INTO logs(id,user_id,text,kind,t) VALUES(?,?,?,?,?)", (new_id(), uid, text[:300], kind if kind in ('info', 'signup', 'login', 'admin', 'warn') else 'info', now_ms()))
        self.db.x("DELETE FROM logs WHERE rowid IN (SELECT rowid FROM logs ORDER BY t ASC LIMIT max(0,(SELECT count(*) FROM logs)-5000))")
    def notif(self, text, icon='bell'):
        self.db.x("INSERT INTO notifs(id,text,icon,t,read) VALUES(?,?,?,?,0)", (new_id(), text[:300], icon[:20], now_ms()))
        self.db.x("DELETE FROM notifs WHERE rowid IN (SELECT rowid FROM notifs ORDER BY t ASC LIMIT max(0,(SELECT count(*) FROM notifs)-500))")

    # ---- user creation
    def make_username(self, base):
        u = re.sub(r'[^a-z0-9_.]', '', (base or '').lower())[:16]
        if len(u) < 3: u = 'user' + str(secrets.randbelow(90000) + 10000)
        cand = u
        for i in range(30):
            if not self.db.one("SELECT 1 FROM users WHERE username=?", (cand,)): return cand
            cand = u[:16] + str(secrets.randbelow(9000) + 100)
        return 'user' + secrets.token_hex(5)
    def create_user(self, name, email, phone, pw, base_username, profile=None):
        n = now_ms()
        for _ in range(5):
            uid = new_uid(); uname = self.make_username(base_username or name)
            try:
                self.db.x("INSERT INTO users(id,username,name,email,phone,pw_hash,created_at,trial_until,last_login,login_count,profile) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                          (uid, uname, name, email or None, phone or None, hash_pw(pw) if pw else None, n, n + 30 * DAY, n, 1, json.dumps(profile or {})))
                return uid, uname
            except sqlite3.IntegrityError as e:
                m = str(e)
                if 'users.email' in m or 'users.phone' in m: raise ApiError(409, 'exists', {'msg': 'An account with this email or phone already exists'})
                continue
        raise ApiError(500, 'server_error')

    # ---- routes
    def _reg(self):
        R = self.routes
        for name in dir(self):
            if name.startswith('h_'):
                fn = getattr(self, name)
                meth, _, path = fn.__doc__.strip().partition(' ')
                # doc: "METHOD /path [auth] [maxbody]"
                parts = path.split()
                R[(meth, parts[0])] = (fn, parts[1] if len(parts) > 1 else 'anon', int(parts[2]) if len(parts) > 2 else 65536)
        # dynamic admin routes are matched with regex below
    DYN = []

    # ======================================================== public / session
    def h_session(self, ctx):
        """GET /api/session anon"""
        n = now_ms()
        d = {'serverTime': n, 'site': self.public_site(),
             'providers': {'google': bool(self.cfg['google_id'] and self.cfg['google_secret'] and self.cfg['base_url']), 'telegram': bool(self.cfg['tg_token']), 'tgBot': self.tg_user},
             'user': None, 'admin': None}
        if ctx.user:
            d['user'] = self.user_view(ctx.user); d['csrf'] = ctx.session['csrf']
        if ctx.admin:
            d['admin'] = {'username': ctx.admin['username'], 'csrf': ctx.asession['csrf']}
        return 200, d

    def h_signup(self, ctx):
        """POST /api/signup anon"""
        if ctx.user: raise ApiError(400, 'already_signed_in')
        if not self.site()['registrationOpen']: raise ApiError(403, 'closed', {'msg': 'Registration is closed right now'})
        if not self.lim.hit('signup:' + ctx.ip, int(os.environ.get('LUMI_SIGNUP_LIMIT', '8')), 3600): raise ApiError(429, 'rate', {'msg': 'Too many attempts. Try again later'})
        b = ctx.body
        name = s_txt(b.get('name'), 30); email = s_txt(b.get('email'), 80, False).lower(); phone = norm_phone(b.get('phone')); pw = b.get('password')
        if not name or not email or not pw: raise ApiError(400, 'missing', {'msg': 'Please fill in all fields'})
        if not EMAIL_RE.match(email): raise ApiError(400, 'bad_email', {'msg': 'Enter a valid email'})
        if phone and not PHONE_RE.match(phone): raise ApiError(400, 'bad_phone', {'msg': 'Enter a valid phone number'})
        if not pw_ok(pw): raise ApiError(400, 'weak_pw', {'msg': PW_MSG})
        prof = self.clean_profile(b.get('profile'), sanitize_vip(self.site().get('vip'))['freePhotos']) if isinstance(b.get('profile'), dict) else {}
        uid, uname = self.create_user(name, email, phone, pw, b.get('username') or email.split('@')[0], prof)
        self.log(uid, 'ثبت‌نام در سایت و ساخت پوشه‌ی /users/' + uname, 'signup')
        self.notif('کاربر جدید «%s» ثبت‌نام کرد؛ پوشه‌ی @%s ساخته شد' % (name, uname), 'folderplus')
        self.new_session(ctx, uid)
        u = self.db.one("SELECT * FROM users WHERE id=?", (uid,))
        return 200, {'user': self.user_view(u), 'csrf': ctx.new_csrf}

    def h_login(self, ctx):
        """POST /api/login anon"""
        b = ctx.body
        idf = s_txt(b.get('id'), 80, False).lower(); pw = b.get('password')
        if not idf or not isinstance(pw, str) or len(pw) > 128: raise ApiError(400, 'missing', {'msg': 'Enter your email and password'})
        ik = 'lf-id:' + sha(idf)
        if self.lim.count('lf-ip:' + ctx.ip, 900) >= 25 or self.lim.count(ik, 900) >= 8:
            raise ApiError(429, 'rate', {'msg': 'Too many attempts. Try again in a moment'})
        ph = norm_phone(idf)
        u = self.db.one("SELECT * FROM users WHERE email=? OR username=? OR (phone IS NOT NULL AND phone=?)", (idf, idf, ph if PHONE_RE.match(ph) else '\x00'))
        ok = verify_pw(pw, u['pw_hash'] if u else None) if True else False
        if not u or not ok:
            self.lim.hit('lf-ip:' + ctx.ip, 10 ** 6, 900); self.lim.hit(ik, 10 ** 6, 900)
            raise ApiError(401, 'bad_credentials', {'msg': 'Wrong account or password'})
        if u['status'] != 'active' or u['deleted']:
            raise ApiError(403, 'inactive', {'msg': 'This account is not active. Please contact support.'})
        self.lim.clear(ik)
        self.db.x("UPDATE users SET last_login=?,login_count=login_count+1 WHERE id=?", (now_ms(), u['id']))
        self.log(u['id'], 'ورود به حساب', 'login')
        self.new_session(ctx, u['id'])
        u = self.db.one("SELECT * FROM users WHERE id=?", (u['id'],))
        return 200, {'user': self.user_view(u), 'csrf': ctx.new_csrf}

    def h_logout(self, ctx):
        """POST /api/logout anon"""
        if ctx.session: self.db.x("DELETE FROM sessions WHERE id=?", (ctx.session['id'],))
        ctx.cookies.append(self.cookie('s', '', 0))
        return 200, {'ok': True}

    def h_password(self, ctx):
        """POST /api/password user"""
        u = ctx.user; b = ctx.body; cur = b.get('current'); new = b.get('new')
        if not pw_ok(new): raise ApiError(400, 'weak_pw', {'msg': PW_MSG})
        if not self.lim.hit('pwch:' + u['id'], 10, 900): raise ApiError(429, 'rate', {'msg': 'Too many attempts. Try again in a moment'})
        if u['pw_hash']:
            if u['must_change'] and not cur: pass          # temporary password was just used to sign in
            elif not isinstance(cur, str) or not verify_pw(cur, u['pw_hash']): raise ApiError(403, 'bad_current', {'msg': 'Current password is wrong'})
        self.db.x("UPDATE users SET pw_hash=?,must_change=0 WHERE id=?", (hash_pw(new), u['id']))
        self.db.x("DELETE FROM sessions WHERE user_id=?", (u['id'],))       # every old session dies; this one is re-issued
        self.new_session(ctx, u['id'])
        self.log(u['id'], 'رمز توسط کاربر تغییر کرد', 'info')
        return 200, {'ok': True, 'csrf': ctx.new_csrf}

    def clean_profile(self, p, maxph, vip=False):
        if not isinstance(p, dict): raise ApiError(400, 'bad_profile')
        if len(json.dumps(p)) > 10 * 1024 * 1024: raise ApiError(413, 'too_big')
        out = {}
        for k, v in p.items():
            if not isinstance(k, str) or len(k) > 40 or k in ('__proto__', 'constructor', 'prototype'): continue
            if k == 'photos': continue
            if k in ('email', 'phone', 'user', 'name', 'bio', 'city', 'cityn', 'gender') and not isinstance(v, str): continue
            out[k] = v
        ph = p.get('photos', [])
        if not isinstance(ph, list): ph = []
        out['photos'] = [x for x in ph if img_ok(x)][:maxph]
        v = p.get('video')
        vcfg = sanitize_vip((self.site() or {}).get('vip'))
        out['video'] = v if (vip and isinstance(v, str) and video_ok(v, vcfg['videoMB'] * 1024 * 1024)) else ''
        return out

    def h_profile(self, ctx):
        """POST /api/me/profile user 12000000"""
        u = ctx.user; b = ctx.body
        site = self.site()
        vc = sanitize_vip(site.get('vip')); vp = self.is_vip(u)
        perks = vc['perks']
        vp_photos = vp or perks['photos'] == 'all'
        vp_video = (vp and perks['video'] != 'off') or perks['video'] == 'all'
        prof = self.clean_profile(b.get('profile'), vc['vipPhotos'] if vp_photos else vc['freePhotos'], vp_video)
        name = s_txt(prof.get('name') or u['name'], 30) or u['name']
        age = age_from_dob(prof.get('dob')) or _int(prof.get('age'), 18, 99, u['age'])
        gender = prof.get('gender') if prof.get('gender') in ('Man', 'Woman', 'm', 'f', '') else ''
        city = s_txt(prof.get('cityn') or prof.get('city') or '', 40)
        bio = s_txt(prof.get('bio') or '', 600)
        ints = [s_txt(x, 30) for x in (prof.get('interests') if isinstance(prof.get('interests'), list) else [])[:12] if isinstance(x, str)]
        gcode = 'm' if gender in ('Man', 'm') else 'f' if gender in ('Woman', 'f') else ''
        # identity/contact fields are never taken from the blob
        for k in ('email', 'phone', 'id', 'username'): prof.pop(k, None)
        pct = prof_pct(prof)
        self.db.x("UPDATE users SET profile=?,name=?,age=?,gender=?,city=?,bio=?,interests=?,pct=? WHERE id=?",
                  (json.dumps(prof, ensure_ascii=False), name, age, gcode, city, bio, json.dumps(ints, ensure_ascii=False), pct, u['id']))
        return 200, {'ok': True}

    def h_delete_me(self, ctx):
        """POST /api/me/delete user"""
        u = ctx.user
        self.db.x("UPDATE users SET deleted=1,status='banned' WHERE id=?", (u['id'],))
        self.db.x("DELETE FROM sessions WHERE user_id=?", (u['id'],))
        self.log(u['id'], 'کاربر حساب خود را حذف کرد', 'info')
        ctx.cookies.append(self.cookie('s', '', 0))
        return 200, {'ok': True}

    def h_visit(self, ctx):
        """POST /api/visit anon 1024"""
        if self.lim.hit('visit:' + ctx.ip, 30, 60): self.db.x("INSERT INTO visits(t) VALUES(?)", (now_ms(),))
        return 200, {'ok': True}

    def h_chatlog(self, ctx):
        """POST /api/chatlog user 4096"""
        u = ctx.user; b = ctx.body
        if not self.lim.hit('chat:' + u['id'], 120, 60): raise ApiError(429, 'rate')
        cid = s_txt(b.get('cid'), 40, False)
        if not re.match(r'^[A-Za-z0-9_\-]{1,40}$', cid): raise ApiError(400, 'bad')
        text = s_txt(b.get('text'), 2000, False)
        if not text: raise ApiError(400, 'bad')
        me = b.get('dir') == 'out'
        words = self.site()['blockedWords']
        flagged = 1 if me and self.site().get('autoFlag', True) and any(w and w in text for w in words) else 0
        self.db.x("INSERT INTO chatlog(id,sender,receiver,text,t,flagged,pn) VALUES(?,?,?,?,?,?,?)",
                  (new_id(), u['id'] if me else 'p:' + cid, 'p:' + cid if me else u['id'], text, now_ms(), flagged, s_txt(b.get('pn'), 40)))
        if flagged: self.notif('پیام مشکوک ثبت شد', 'flag')
        self.db.x("DELETE FROM chatlog WHERE rowid IN (SELECT rowid FROM chatlog ORDER BY t ASC LIMIT max(0,(SELECT count(*) FROM chatlog)-20000))")
        return 200, {'ok': True}

    # ---- people (discover), likes, matches, profile visits and direct messages
    def pub_user(self, r, full=False):
        """the ONLY shape other people ever get to see — whitelisted fields, never email/phone/ids of contact data"""
        try: p = json.loads(r['profile'] or '{}')
        except Exception: p = {}
        ph = [x for x in (p.get('photos') if isinstance(p.get('photos'), list) else []) if isinstance(x, str) and x.startswith('data:image/')]
        life = p.get('life') if isinstance(p.get('life'), dict) else {}
        g = 'Man' if r['gender'] == 'm' else 'Woman' if r['gender'] == 'f' else ''
        d = {'id': r['id'], 'username': r['username'], 'name': r['name'], 'age': r['age'] or 0, 'gender': g,
             'photos': ph if full else ph[:1], 'nph': len(ph), 'vip': self.is_vip(r), 'pct': r['pct'],
             'job': s_txt(p.get('job'), 60), 'prov': s_txt(p.get('prov'), 40), 'cityn': s_txt(p.get('cityn'), 40), 'bio': s_txt(p.get('bio'), 600),
             'goal': s_txt(p.get('goal'), 40), 'belief': s_txt(p.get('belief'), 40), 'relig': s_txt(p.get('relig'), 40), 'edu': s_txt(p.get('edu'), 60),
             'height': _int(p.get('height'), 0, 260, 0), 'weight': _int(p.get('weight'), 0, 400, 0),
             'interests': _strs(p.get('interests'), 12, 30), 'langs': _strs(p.get('langs'), 16, 30), 'values': _strs(p.get('values'), 12, 40),
             'life': {s_txt(k, 30): s_txt(v, 60) for k, v in list(life.items())[:12] if isinstance(k, str) and isinstance(v, str) and v},
             'insta': s_txt(p.get('insta'), 40) if p.get('instaShow') is True else ''}
        return d
    def visible_user(self, r):
        return bool(r) and r['status'] == 'active' and not r['deleted'] and r['pct'] >= MINPCT and (r['age'] or 0) >= 18
    def h_people(self, ctx):
        """GET /api/people anon"""
        if not self.lim.hit('ppl:' + ctx.ip, 90, 60): raise ApiError(429, 'rate')
        me = ctx.user['id'] if ctx.user else ''
        off = _int(ctx.query.get('off'), 0, 100000, 0)
        rows = self.db.q("SELECT * FROM users WHERE status='active' AND deleted=0 AND pct>=? AND age>=18 AND id<>? ORDER BY last_login DESC LIMIT 40 OFFSET ?", (MINPCT, me, off))
        return 200, {'users': [self.pub_user(r) for r in rows]}
    def h_person(self, ctx):
        """GET /api/person anon"""
        if not self.lim.hit('prs:' + ctx.ip, 120, 60): raise ApiError(429, 'rate')
        uid = str(ctx.query.get('id', ''))
        if not UID_RE.match(uid): raise ApiError(400, 'bad_id')
        r = self.db.one("SELECT * FROM users WHERE id=?", (uid,))
        if not self.visible_user(r): raise ApiError(404, 'no_user')
        if ctx.user and ctx.user['id'] != uid and ctx.user['pct'] >= MINPCT:
            self.db.x("INSERT INTO pvisits(from_id,to_id,t) VALUES(?,?,?) ON CONFLICT(from_id,to_id) DO UPDATE SET t=excluded.t", (ctx.user['id'], uid, now_ms()))
        return 200, {'user': self.pub_user(r, True)}
    def h_social(self, ctx):
        """GET /api/social user"""
        u = ctx.user; me = u['id']
        liked = [r['to_id'] for r in self.db.q("SELECT to_id FROM likes WHERE from_id=? ORDER BY t DESC LIMIT 2000", (me,))]
        lm = [{'id': r['from_id'], 't': r['t']} for r in self.db.q("SELECT from_id,t FROM likes WHERE to_id=? ORDER BY t DESC LIMIT 500", (me,))]
        vs = [{'id': r['from_id'], 't': r['t']} for r in self.db.q("SELECT from_id,t FROM pvisits WHERE to_id=? ORDER BY t DESC LIMIT 200", (me,))]
        dm = [{'id': r['id'], 'f': r['from_id'], 'to': r['to_id'], 'text': r['text'], 't': r['t']}
              for r in self.db.q("SELECT * FROM dms WHERE from_id=? OR to_id=? ORDER BY t DESC LIMIT 600", (me, me))][::-1]
        ids = []
        for x in liked[:300] + [y['id'] for y in lm[:300]] + [y['id'] for y in vs[:100]] + [m['f'] if m['f'] != me else m['to'] for m in dm]:
            if x not in ids: ids.append(x)
            if len(ids) >= 300: break
        peers = []
        if ids:
            for r in self.db.q("SELECT * FROM users WHERE id IN (%s) AND status='active' AND deleted=0" % ','.join('?' * len(ids)), ids):
                peers.append(self.pub_user(r))
        return 200, {'liked': liked, 'likedMe': lm, 'visits': vs, 'dms': dm, 'peers': peers, 'serverTime': now_ms()}
    def need_ready(self, u):
        if u['status'] != 'active' or u['deleted']: raise ApiError(403, 'blocked')
        if u['pct'] < MINPCT: raise ApiError(403, 'profile_incomplete', {'msg': 'Complete your profile to 70% first'})
        if not self.sub_ok(u): raise ApiError(403, 'sub_required', {'msg': 'Your membership has ended'})
    def perk(self, u, k):
        a = sanitize_vip(self.site().get('vip'))['perks'].get(k, 'vip')
        return a == 'all' or (a == 'vip' and self.is_vip(u))
    def mutual(self, a, b):
        return bool(self.db.one("SELECT 1 FROM likes x JOIN likes y ON y.from_id=x.to_id AND y.to_id=x.from_id WHERE x.from_id=? AND x.to_id=?", (a, b)))
    def h_like(self, ctx):
        """POST /api/like user 1024"""
        u = ctx.user; self.need_ready(u)
        tid = str(ctx.body.get('id', ''))
        if not UID_RE.match(tid) or tid == u['id']: raise ApiError(400, 'bad_id')
        t = self.db.one("SELECT * FROM users WHERE id=?", (tid,))
        if not self.visible_user(t): raise ApiError(404, 'no_user')
        if not self.lim.hit('like:' + u['id'], 60, 60): raise ApiError(429, 'rate')
        if not self.db.one("SELECT 1 FROM likes WHERE from_id=? AND to_id=?", (u['id'], tid)):
            if not self.perk(u, 'unlimited'):
                cap = sanitize_vip(self.site().get('vip'))['dailyLikes']
                if self.db.one("SELECT count(*) n FROM likes WHERE from_id=? AND t>?", (u['id'], now_ms() - DAY))['n'] >= cap:
                    raise ApiError(403, 'like_limit', {'msg': 'Daily like limit reached', 'limit': cap})
            self.db.x("INSERT OR IGNORE INTO likes(from_id,to_id,t) VALUES(?,?,?)", (u['id'], tid, now_ms()))
        return 200, {'ok': True, 'matched': self.mutual(u['id'], tid)}
    def h_unlike(self, ctx):
        """POST /api/like/delete user 1024"""
        u = ctx.user; tid = str(ctx.body.get('id', ''))
        if not UID_RE.match(tid): raise ApiError(400, 'bad_id')
        self.db.x("DELETE FROM likes WHERE from_id=? AND to_id=?", (u['id'], tid))
        return 200, {'ok': True}
    def h_dm_send(self, ctx):
        """POST /api/dm/send user 2048"""
        u = ctx.user; self.need_ready(u)
        tid = str(ctx.body.get('to', ''))
        if not UID_RE.match(tid) or tid == u['id']: raise ApiError(400, 'bad_id')
        t = self.db.one("SELECT * FROM users WHERE id=?", (tid,))
        if not self.visible_user(t): raise ApiError(404, 'no_user')
        text = s_txt(ctx.body.get('text'), 500)
        if not text: raise ApiError(400, 'empty')
        if not self.lim.hit('dm1:' + u['id'], 1, 0.3) or not self.lim.hit('dm:' + u['id'], 60, 60): raise ApiError(429, 'rate', {'msg': 'Slow down'})
        if not self.mutual(u['id'], tid):
            # not matched: only the VIP "message before matching" perk, one short message per person, limited per day
            if not self.perk(u, 'dm'): raise ApiError(403, 'not_matched', {'msg': 'You can chat after you match'})
            if self.db.one("SELECT 1 FROM dms WHERE from_id=? AND to_id=?", (u['id'], tid)): raise ApiError(403, 'not_matched', {'msg': 'Wait for a reply or a match'})
            cap = sanitize_vip(self.site().get('vip'))['dmDaily']
            if self.db.one("SELECT count(*) n FROM dms WHERE from_id=? AND t>? AND NOT EXISTS (SELECT 1 FROM likes a JOIN likes b ON b.from_id=a.to_id AND b.to_id=a.from_id WHERE a.from_id=dms.from_id AND a.to_id=dms.to_id)", (u['id'], now_ms() - DAY))['n'] >= cap:
                raise ApiError(403, 'dm_limit', {'msg': 'Daily message limit reached'})
            text = text[:140]
        mid = new_id(); n = now_ms()
        self.db.x("INSERT INTO dms(id,from_id,to_id,text,t) VALUES(?,?,?,?,?)", (mid, u['id'], tid, text, n))
        self.db.x("DELETE FROM dms WHERE rowid IN (SELECT rowid FROM dms WHERE from_id=? AND to_id=? ORDER BY t DESC LIMIT -1 OFFSET 3000)", (u['id'], tid))
        return 200, {'ok': True, 'id': mid, 't': n}

    # ---- public group (everyone signed in with an active trial / membership can talk; roles are computed on the SERVER)
    def sub_ok(self, u):
        n = now_ms()
        return u['trial_until'] > n or (bool(u['premium']) and (u['premium_until'] == 0 or u['premium_until'] > n))
    def group_on(self): return self.site()['features'].get('group', True) is not False
    def grole(self, r):
        if r is None: return 'admin'
        if r['group_admin']: return 'admin'
        return 'vip' if self.is_vip(r) else 'regular'
    def group_rows(self, me):
        out = []
        rows = self.db.q("SELECT g.id,g.user_id,g.name AS gname,g.text,g.t,g.adm,u.name,u.premium,u.premium_until,u.tier,u.group_admin,u.status,u.deleted "
                         "FROM group_msgs g LEFT JOIN users u ON u.id=g.user_id ORDER BY g.t DESC LIMIT 300")
        for r in reversed(rows):
            if r['user_id'] and (r['status'] != 'active' or r['deleted']): continue
            if r['adm'] or not r['user_id']:
                uid, name, role = 'admin', r['gname'] or 'LUMI Team', 'admin'
            else:
                role = 'admin' if r['group_admin'] else ('vip' if (r['premium'] and r['tier'] != 'regular' and (r['premium_until'] == 0 or r['premium_until'] > now_ms())) else 'regular')
                uid = r['user_id'] if r['user_id'] == me else 'x' + sha('grp:' + r['user_id'])[:12]      # other people's ids are never exposed
                name = r['name']
            out.append({'id': r['id'], 'uid': uid, 'name': name, 'text': r['text'], 't': r['t'], 'role': role, 'adm': role == 'admin' and uid == 'admin'})
        return out
    def h_group(self, ctx):
        """GET /api/group user"""
        if not self.group_on(): raise ApiError(403, 'group_off', {'msg': 'Group is unavailable'})
        u = ctx.user
        if u['pct'] < MINPCT: raise ApiError(403, 'profile_incomplete', {'msg': 'Complete your profile to 70% first'})
        return 200, {'messages': self.group_rows(u['id']), 'admin': bool(u['group_admin']), 'muted': bool(u['group_muted'])}
    def h_group_send(self, ctx):
        """POST /api/group/send user 2048"""
        u = ctx.user
        if not self.group_on(): raise ApiError(403, 'group_off', {'msg': 'Group is unavailable'})
        if u['status'] != 'active' or u['deleted']: raise ApiError(403, 'blocked')
        if u['pct'] < MINPCT: raise ApiError(403, 'profile_incomplete', {'msg': 'Complete your profile to 70% first'})
        if u['group_muted']: raise ApiError(403, 'muted', {'msg': 'You are muted'})
        if not self.sub_ok(u): raise ApiError(403, 'sub_required', {'msg': 'Your membership has ended'})
        text = s_txt(ctx.body.get('text'), 600)
        text = text[:500].strip()
        if not text: raise ApiError(400, 'empty')
        if not self.lim.hit('grp1:' + u['id'], 1, 1) or not self.lim.hit('grp:' + u['id'], 40, 60): raise ApiError(429, 'rate', {'msg': 'Slow down'})
        low = text.lower()
        if any(w and w.lower() in low for w in self.site()['blockedWords']): raise ApiError(400, 'blocked_word', {'msg': 'This message is not allowed'})
        self.db.x("INSERT INTO group_msgs(id,user_id,name,text,t,adm) VALUES(?,?,?,?,?,0)", (new_id(), u['id'], u['name'], text, now_ms()))
        self.db.x("DELETE FROM group_msgs WHERE rowid IN (SELECT rowid FROM group_msgs ORDER BY t ASC LIMIT max(0,(SELECT count(*) FROM group_msgs)-5000))")
        return 200, {'messages': self.group_rows(u['id'])}
    def h_group_del(self, ctx):
        """POST /api/group/delete user 1024"""
        u = ctx.user; mid = str(ctx.body.get('id', ''))
        if not re.match(r'^[A-Za-z0-9_\-]{1,40}$', mid): raise ApiError(400, 'bad')
        m = self.db.one("SELECT * FROM group_msgs WHERE id=?", (mid,))
        if not m: raise ApiError(404, 'no_message')
        if not (m['user_id'] == u['id'] or u['group_admin']): raise ApiError(403, 'forbidden')     # own message, or group admin
        self.db.x("DELETE FROM group_msgs WHERE id=?", (mid,))
        if m['user_id'] != u['id']: self.audit(ctx, 'u:' + u['id'], 'group_delete', mid)
        return 200, {'messages': self.group_rows(u['id'])}

    # ---- support (users by session, guests by secret gid)
    def thread_rows(self, th):
        return [{'id': r['id'], 'from': r['sender'], 'text': r['text'], 't': r['t'], 'read': bool(r['read'])} for r in
                self.db.q("SELECT * FROM support WHERE thread=? ORDER BY t,rowid LIMIT 300", (th,))]
    def add_support(self, th, text):
        if not self.lim.hit('sup:' + th, 20, 3600): raise ApiError(429, 'rate', {'msg': 'Too many messages. Try again later'})
        text = s_txt(text, 1000, False)
        if not text: raise ApiError(400, 'empty')
        n = self.db.one("SELECT count(*) c FROM support WHERE thread=? AND sender='u' AND read=0", (th,))['c']
        if n >= 30: raise ApiError(429, 'rate', {'msg': 'Too many unanswered messages'})
        mid = new_id()
        self.db.x("INSERT INTO support(id,thread,sender,text,t,read) VALUES(?,?,?,?,?,0)", (mid, th, 'u', text, now_ms()))
        self.notif('پیام جدید پشتیبانی', 'msg')
        return mid
    def h_support_get(self, ctx):
        """GET /api/support user"""
        th = ctx.user['id']
        self.db.x("UPDATE support SET read=1 WHERE thread=? AND sender='a'", (th,))
        return 200, {'messages': self.thread_rows(th)}
    def h_support_post(self, ctx):
        """POST /api/support user 8192"""
        self.add_support(ctx.user['id'], ctx.body.get('text'))
        return 200, {'messages': self.thread_rows(ctx.user['id'])}
    def h_support_guest_get(self, ctx):
        """POST /api/support/guest anon 8192"""
        gid = ctx.body.get('gid')
        if not isinstance(gid, str) or not re.match(r'^g[a-z0-9]{10,24}$', gid): raise ApiError(400, 'bad_gid')
        if not self.lim.hit('sg:' + ctx.ip, 60, 3600): raise ApiError(429, 'rate')
        if isinstance(ctx.body.get('text'), str) and ctx.body['text'].strip(): self.add_support(gid, ctx.body['text'])
        return 200, {'messages': self.thread_rows(gid)}

    # ---- payments
    def pay_view(self, r):
        return {'id': r['id'], 'plan': r['plan_id'], 'planName': r['plan_name'], 'amount': r['amount'], 'period': r['period'], 'tier': r['tier'], 't': r['created'], 'status': r['status'], 'note': r['note']}
    def h_pay_list(self, ctx):
        """GET /api/payments user"""
        return 200, {'payments': [self.pay_view(r) for r in self.db.q("SELECT * FROM payments WHERE user_id=? ORDER BY created DESC LIMIT 100", (ctx.user['id'],))]}
    def h_pay_create(self, ctx):
        """POST /api/payments user 4200000"""
        u = ctx.user; b = ctx.body
        if not self.lim.hit('pay-try:' + u['id'], 60, 3600): raise ApiError(429, 'rate', {'msg': 'Too many attempts. Try again later'})
        plan = self.plan(str(b.get('plan', '')))
        if not plan: raise ApiError(404, 'no_plan', {'msg': 'This plan is not available'})
        amount = int(plan['price'])           # the price ALWAYS comes from the server — never from the client
        if b.get('amount') is not None and b.get('amount') != amount:
            raise ApiError(409, 'price_changed', {'msg': 'The price changed. Please review and try again.', 'amount': amount})
        if not self.site()['pay']['card']: raise ApiError(409, 'no_card', {'msg': 'Payment details are not set yet. Please contact support.'})
        rc = b.get('receipt')
        if not img_ok(rc, 2 * 1024 * 1024): raise ApiError(400, 'bad_receipt', {'msg': 'Only JPG, PNG or WEBP images'})
        if not self.lim.hit('pay:' + u['id'], 10, 86400): raise ApiError(429, 'rate', {'msg': 'Too many receipts today'})
        with self.db.tx() as c:
            if c.execute("SELECT count(*) FROM payments WHERE user_id=? AND status='pending'", (u['id'],)).fetchone()[0] >= 3:
                raise ApiError(429, 'too_many_pending', {'msg': 'Too many pending receipts'})
            pid = new_id()
            c.execute("INSERT INTO payments(id,user_id,plan_id,plan_name,period,amount,days,created,receipt,tier) VALUES(?,?,?,?,?,?,?,?,?,?)",
                      (pid, u['id'], plan['id'], plan['name'], plan['period'], amount, PERDAYS[plan['period']], now_ms(), rc, plan.get('tier') or 'regular'))
        self.notif('رسید پرداخت جدید از «@%s» — %s (%s تومان)' % (u['username'], plan['name'], format(amount, ',')), 'zap')
        self.log(u['id'], 'ارسال رسید پرداخت اشتراک «%s»' % plan['name'], 'info')
        return 200, {'payment': self.pay_view(self.db.one("SELECT * FROM payments WHERE id=?", (pid,)))}

    # ======================================================== social login (Google / Telegram) — identities are bound 1:1
    def need_csrf(self, ctx):
        if not ctx.session or not hmac.compare_digest(ctx.headers.get('X-CSRF-Token', '') or '', ctx.session['csrf']):
            raise ApiError(403, 'csrf', {'msg': 'Session expired. Please reload.'})

    def social_finish(self, ctx, provider, subject, display, email, name, kind, link_uid):
        subject = str(subject)[:100]; display = s_txt(str(display or ''), 120, False)
        for _ in range(3):
            row = self.db.one("SELECT user_id FROM identities WHERE provider=? AND subject=?", (provider, subject))
            if kind == 'link':
                if not link_uid: raise ApiError(403, 'login_required')
                if row:
                    if row['user_id'] == link_uid: return link_uid, False
                    raise ApiError(409, 'identity_in_use', {'msg': 'This %s account is already linked to another LUMI account' % provider})
                if self.db.one("SELECT 1 FROM identities WHERE user_id=? AND provider=?", (link_uid, provider)):
                    raise ApiError(409, 'provider_already_linked', {'msg': 'Your account already has a %s account linked' % provider})
                try:
                    self.db.x("INSERT INTO identities(user_id,provider,subject,display,created_at) VALUES(?,?,?,?,?)", (link_uid, provider, subject, display, now_ms()))
                except sqlite3.IntegrityError:
                    raise ApiError(409, 'identity_in_use', {'msg': 'This %s account is already linked to another LUMI account' % provider})
                self.log(link_uid, 'اتصال حساب %s' % provider, 'info')
                return link_uid, False
            if row:
                u = self.db.one("SELECT * FROM users WHERE id=?", (row['user_id'],))
                if not u or u['status'] != 'active' or u['deleted']: raise ApiError(403, 'inactive', {'msg': 'This account is not active. Please contact support.'})
                self.db.x("UPDATE users SET last_login=?,login_count=login_count+1 WHERE id=?", (now_ms(), u['id']))
                self.log(u['id'], 'ورود با %s' % provider, 'login')
                return u['id'], False
            # first time → create a new account bound to this identity
            if not self.site()['registrationOpen']: raise ApiError(403, 'closed', {'msg': 'Registration is closed right now'})
            em = (email or '').lower()
            if not EMAIL_RE.match(em) or self.db.one("SELECT 1 FROM users WHERE email=?", (em,)): em = ''
            nm = s_txt(name, 30) or ('User' + str(secrets.randbelow(9000) + 1000))
            uid, uname = self.create_user(nm, em, '', None, (em.split('@')[0] if em else nm) or provider)
            try:
                self.db.x("INSERT INTO identities(user_id,provider,subject,display,created_at) VALUES(?,?,?,?,?)", (uid, provider, subject, display, now_ms()))
            except sqlite3.IntegrityError:
                self.db.x("DELETE FROM users WHERE id=?", (uid,)); continue      # lost a race with the same identity → retry as login
            self.log(uid, 'ثبت‌نام با %s و ساخت پوشه‌ی /users/%s' % (provider, uname), 'signup')
            self.notif('کاربر جدید «%s» با %s ثبت‌نام کرد' % (nm, provider), 'folderplus')
            return uid, True
        raise ApiError(409, 'conflict')

    def h_google_start(self, ctx):
        """POST /api/auth/google/start anon 1024"""
        c = self.cfg
        if not (c['google_id'] and c['google_secret'] and c['base_url']): raise ApiError(503, 'not_configured', {'msg': 'Google sign-in is not configured on this server'})
        if not self.lim.hit('gs:' + ctx.ip, 20, 600): raise ApiError(429, 'rate')
        kind = 'link' if ctx.body.get('mode') == 'link' else 'login'
        if kind == 'link': self.need_csrf(ctx)
        state, nonce, ver = tok(), tok(), tok(48)
        chal = base64.urlsafe_b64encode(hashlib.sha256(ver.encode()).digest()).rstrip(b'=').decode()
        self.db.x("INSERT INTO oauth_states(state_hash,nonce_hash,verifier,kind,user_id,expires) VALUES(?,?,?,?,?,?)",
                  (sha(state), sha(nonce), ver, kind, ctx.user['id'] if (kind == 'link' and ctx.user) else None, now_ms() + 600000))
        q = urllib.parse.urlencode({'client_id': c['google_id'], 'redirect_uri': c['base_url'] + '/api/auth/google/callback', 'response_type': 'code',
                                    'scope': 'openid email profile', 'state': state, 'code_challenge': chal, 'code_challenge_method': 'S256', 'prompt': 'select_account'})
        ctx.cookies.append(self.cookie('o', nonce, 600))
        return 200, {'url': c['google_auth_url'] + '?' + q}

    def http_json(self, url, data=None, timeout=10):
        req = urllib.request.Request(url, data=urllib.parse.urlencode(data).encode() if data is not None else None,
                                     headers={'User-Agent': 'lumi-server', 'Accept': 'application/json'})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read(1 << 20).decode())

    def google_callback(self, ctx):
        """returns redirect location"""
        q = ctx.query
        def fail(code): return '/?auth=err&c=' + code
        state = q.get('state', ''); code = q.get('code', '')
        nonce = self.read_cookie(ctx, 'o')
        ctx.cookies.append(self.cookie('o', '', 0))
        if not state or not code or not nonce or len(state) > 100 or len(code) > 2000: return fail('bad_request')
        with self.db.tx() as c:
            row = c.execute("SELECT * FROM oauth_states WHERE state_hash=?", (sha(state),)).fetchone()
            if row: c.execute("DELETE FROM oauth_states WHERE state_hash=?", (sha(state),))     # single use
        if not row or row['expires'] < now_ms() or not hmac.compare_digest(row['nonce_hash'], sha(nonce)): return fail('bad_state')
        try:
            tk = self.http_json(self.cfg['google_token_url'], {'code': code, 'client_id': self.cfg['google_id'], 'client_secret': self.cfg['google_secret'],
                                'redirect_uri': self.cfg['base_url'] + '/api/auth/google/callback', 'grant_type': 'authorization_code', 'code_verifier': row['verifier']})
            idt = tk['id_token'].split('.')
            pl = json.loads(base64.urlsafe_b64decode(idt[1] + '=' * (-len(idt[1]) % 4)).decode())
        except Exception:
            return fail('google_failed')
        if pl.get('iss') not in ('accounts.google.com', 'https://accounts.google.com') or pl.get('aud') != self.cfg['google_id'] \
                or not isinstance(pl.get('exp'), (int, float)) or pl['exp'] < time.time() - 60 or not isinstance(pl.get('sub'), str) or not pl['sub']:
            return fail('bad_token')
        verified = pl.get('email_verified') in (True, 'true')
        email = pl.get('email') if verified and isinstance(pl.get('email'), str) else ''
        link_uid = row['user_id'] if row['kind'] == 'link' else None
        if row['kind'] == 'link':
            if not ctx.user or ctx.user['id'] != link_uid: return fail('session_mismatch')
        try:
            uid, created = self.social_finish(ctx, 'google', pl['sub'], email or pl.get('name', ''), email, pl.get('name') or (email.split('@')[0] if email else ''), row['kind'], link_uid)
        except ApiError as e:
            return fail(e.msg if re.match(r'^[a-z_]+$', e.msg) else 'failed')
        if row['kind'] == 'login': self.new_session(ctx, uid)
        return '/?auth=ok' + ('&new=1' if created else '')

    def h_tg_start(self, ctx):
        """POST /api/auth/telegram/start anon 1024"""
        if not self.cfg['tg_token']: raise ApiError(503, 'not_configured', {'msg': 'Telegram sign-in is not configured on this server'})
        if not self.tg_user: raise ApiError(503, 'bot_offline', {'msg': 'Telegram bot is not reachable right now'})
        if not self.lim.hit('ts:' + ctx.ip, 12, 600): raise ApiError(429, 'rate')
        kind = 'link' if ctx.body.get('mode') == 'link' else 'login'
        if kind == 'link': self.need_csrf(ctx)
        code, poll = tok(18), tok(24)
        self.db.x("INSERT INTO tg_logins(code_hash,poll_hash,kind,user_id,expires) VALUES(?,?,?,?,?)",
                  (sha(code), sha(poll), kind, ctx.user['id'] if (kind == 'link' and ctx.user) else None, now_ms() + 300000))
        return 200, {'code': code, 'poll': poll, 'url': 'https://t.me/%s?start=%s' % (self.tg_user, code), 'bot': self.tg_user}

    def h_tg_poll(self, ctx):
        """POST /api/auth/telegram/poll anon 1024"""
        if not self.lim.hit('tp:' + ctx.ip, 200, 600): raise ApiError(429, 'rate')
        code, poll = ctx.body.get('code'), ctx.body.get('poll')
        if not isinstance(code, str) or not isinstance(poll, str) or len(code) > 80 or len(poll) > 80: raise ApiError(400, 'bad')
        row = self.db.one("SELECT * FROM tg_logins WHERE code_hash=?", (sha(code),))
        if not row or not hmac.compare_digest(row['poll_hash'], sha(poll)): return 200, {'status': 'expired'}
        if row['expires'] < now_ms(): return 200, {'status': 'expired'}
        if row['status'] != 'confirmed': return 200, {'status': 'pending'}
        if row['kind'] == 'link' and (not ctx.user or ctx.user['id'] != row['user_id']): return 200, {'status': 'expired'}
        if row['kind'] == 'link': self.need_csrf(ctx)
        with self.db.tx() as c:
            n = c.execute("DELETE FROM tg_logins WHERE code_hash=? AND status='confirmed'", (sha(code),)).rowcount
        if n != 1: return 200, {'status': 'expired'}
        uid, created = self.social_finish(ctx, 'telegram', row['tg_id'], ('@' + row['tg_name']) if row['tg_name'] else 'Telegram ' + row['tg_id'], '', row['tg_name'] or 'Telegram user', row['kind'], row['user_id'])
        if row['kind'] == 'login': self.new_session(ctx, uid)
        u = self.db.one("SELECT * FROM users WHERE id=?", (uid,))
        return 200, {'status': 'ok', 'user': self.user_view(u), 'csrf': getattr(ctx, 'new_csrf', ctx.session['csrf'] if ctx.session else ''), 'created': created}

    def tg_api(self, method, params=None, timeout=30):
        url = '%s/bot%s/%s' % (self.cfg['tg_api'], self.cfg['tg_token'], method)
        return self.http_json(url, params or {}, timeout)

    def tg_loop(self):
        offset = 0
        while not self.stop.is_set():
            try:
                if not self.tg_user:
                    r = self.tg_api('getMe', None, 15)
                    if r.get('ok'): self.tg_user = r['result'].get('username', '')
                    continue
                r = self.tg_api('getUpdates', {'offset': offset, 'timeout': 20, 'allowed_updates': json.dumps(['message'])}, 40)
                for up in r.get('result', []):
                    offset = max(offset, int(up['update_id']) + 1)
                    try: self.tg_update(up)
                    except Exception: traceback.print_exc()
            except Exception:
                self.stop.wait(3)
    def tg_update(self, up):
        m = up.get('message') or {}
        if (m.get('chat') or {}).get('type') != 'private': return
        fr = m.get('from') or {}
        if fr.get('is_bot') or not isinstance(fr.get('id'), int): return
        txt = m.get('text') or ''
        mm = re.match(r'^/start ([A-Za-z0-9_\-]{10,64})$', txt)
        chat = m['chat']['id']
        if not mm:
            self.tg_api('sendMessage', {'chat_id': chat, 'text': 'Open the LUMI app and tap the Telegram button to sign in.'}, 10); return
        with self.db.tx() as c:
            n = c.execute("UPDATE tg_logins SET status='confirmed',tg_id=?,tg_name=? WHERE code_hash=? AND status='pending' AND expires>?",
                          (str(fr['id']), s_txt(fr.get('username') or '', 40, False), sha(mm.group(1)), now_ms())).rowcount
        self.tg_api('sendMessage', {'chat_id': chat, 'text': '✅ Done! Go back to LUMI — you are signed in.' if n == 1 else 'This sign-in link has expired. Please try again from the app.'}, 10)

    # ======================================================== admin API
    def adm_user(self, r):
        prof = json.loads(r['profile'] or '{}')
        pv = self.providers_of(r['id'])
        return {'id': r['id'], 'username': r['username'], 'name': r['name'], 'phone': r['phone'] or '', 'email': r['email'] or '', 'tg': (pv.get('telegram') or '').lstrip('@')[:32],
                'google': pv.get('google', ''), 'age': r['age'], 'gender': r['gender'], 'city': r['city'], 'bio': r['bio'], 'interests': json.loads(r['interests'] or '[]'),
                'status': r['status'], 'createdAt': r['created_at'], 'lastLogin': r['last_login'], 'loginCount': r['login_count'], 'views': r['views'],
                'likesReceived': r['likes_received'], 'likesSent': r['likes_sent'], 'matches': r['matches'], 'reports': r['reports'], 'premium': bool(r['premium']), 'tier': r['tier'], 'pct': r['pct'], 'groupAdmin': bool(r['group_admin']), 'groupMuted': bool(r['group_muted']),
                'premiumUntil': r['premium_until'], 'trialUntil': r['trial_until'], 'verified': bool(r['verified']), 'starred': bool(r['starred']), 'note': r['note'],
                'deleted': bool(r['deleted']), 'hasPw': bool(r['pw_hash']), 'profile': {'photos': prof.get('photos', [])}}

    def h_adm_login(self, ctx):
        """POST /api/admin/login anon 2048"""
        b = ctx.body; un = s_txt(b.get('username'), 40, False).lower(); pw = b.get('password')
        if not un or not isinstance(pw, str) or len(pw) > 128: raise ApiError(400, 'missing', {'msg': 'نام کاربری و رمز را وارد کنید'})
        ik = 'alf:' + sha(un)
        if self.lim.count('alf-ip:' + ctx.ip, 900) >= 10 or self.lim.count(ik, 900) >= 6:
            raise ApiError(429, 'rate', {'msg': 'تلاش‌های زیاد؛ چند دقیقه بعد دوباره امتحان کنید'})
        a = self.db.one("SELECT * FROM admins WHERE username=?", (un,))
        if not verify_pw(pw, a['pw_hash'] if a else None) or not a:
            self.lim.hit('alf-ip:' + ctx.ip, 10 ** 6, 900); self.lim.hit(ik, 10 ** 6, 900)
            self.audit(ctx, un, 'admin_login_failed')
            raise ApiError(401, 'bad_credentials', {'msg': 'نام کاربری یا رمز اشتباه است'})
        self.lim.clear(ik)
        t = tok(); csrf = tok(24); n = now_ms()
        self.db.x("INSERT INTO admin_sessions(id,admin_id,csrf,created,last_seen,expires) VALUES(?,?,?,?,?,?)", (sha(t), a['id'], csrf, n, n, n + 12 * 3600000))
        ctx.cookies.append(self.cookie('a', t, 12 * 3600))
        self.audit(ctx, un, 'admin_login')
        return 200, {'admin': {'username': a['username'], 'csrf': csrf}}
    def h_adm_logout(self, ctx):
        """POST /api/admin/logout admin"""
        self.db.x("DELETE FROM admin_sessions WHERE id=?", (ctx.asession['id'],))
        ctx.cookies.append(self.cookie('a', '', 0))
        return 200, {'ok': True}
    def h_adm_password(self, ctx):
        """POST /api/admin/password admin"""
        b = ctx.body; a = self.db.one("SELECT * FROM admins WHERE id=?", (ctx.admin['aid'],))
        if not pw_ok(b.get('new')) or len(b['new']) < 10: raise ApiError(400, 'weak_pw', {'msg': 'رمز: حداقل ۱۰ کاراکتر شامل حرف و عدد'})
        if not self.lim.hit('apw:' + str(a['id']), 8, 900): raise ApiError(429, 'rate')
        if not isinstance(b.get('current'), str) or not verify_pw(b['current'], a['pw_hash']): raise ApiError(403, 'bad_current', {'msg': 'رمز فعلی اشتباه است'})
        self.db.x("UPDATE admins SET pw_hash=? WHERE id=?", (hash_pw(b['new']), a['id']))
        self.db.x("DELETE FROM admin_sessions WHERE admin_id=? AND id<>?", (a['id'], ctx.asession['id']))
        self.audit(ctx, a['username'], 'admin_password_changed')
        return 200, {'ok': True}

    STORES = ('users', 'messages', 'notifs', 'logs', 'settings', 'support', 'payments', 'visits', 'group')
    def adm_data(self, ctx, store):
        if store not in self.STORES: raise ApiError(404, 'no_store')
        if store == 'users': return [self.adm_user(r) for r in self.db.q("SELECT * FROM users ORDER BY created_at LIMIT 20000")]
        if store == 'messages': return [{'id': r['id'], 'from': r['sender'], 'to': r['receiver'], 'text': r['text'], 't': r['t'], 'flagged': bool(r['flagged']), 'hidden': bool(r['hidden']), 'pn': r['pn']} for r in self.db.q("SELECT * FROM chatlog ORDER BY t DESC LIMIT 5000")]
        if store == 'notifs': return [{'id': r['id'], 'text': r['text'], 'icon': r['icon'], 't': r['t'], 'read': bool(r['read'])} for r in self.db.q("SELECT * FROM notifs ORDER BY t DESC LIMIT 500")]
        if store == 'logs': return [{'id': r['id'], 'userId': r['user_id'] or '', 'text': r['text'], 'kind': r['kind'], 't': r['t']} for r in self.db.q("SELECT * FROM logs ORDER BY t DESC LIMIT 1500")]
        if store == 'settings': return [self.site()]
        if store == 'support': return [{'id': r['id'], 'userId': r['thread'], 'from': r['sender'], 'text': r['text'], 't': r['t'], 'read': bool(r['read'])} for r in self.db.q("SELECT * FROM support ORDER BY t DESC LIMIT 5000")]
        if store == 'group':
            return [{'id': r['id'], 'uid': r['user_id'] or 'admin', 'name': r['name'] or r['gname'], 'text': r['text'], 't': r['t'], 'adm': bool(r['adm'] or not r['user_id'])}
                    for r in self.db.q("SELECT g.id,g.user_id,g.name AS gname,g.text,g.t,g.adm,u.name FROM group_msgs g LEFT JOIN users u ON u.id=g.user_id ORDER BY g.t DESC LIMIT 1000")][::-1]
        if store == 'payments':
            names = {r['id']: r['username'] for r in self.db.q("SELECT id,username FROM users")}
            return [{'id': r['id'], 'userId': r['user_id'], 'uname': names.get(r['user_id'], ''), 'plan': r['plan_id'], 'planName': r['plan_name'], 'amount': r['amount'], 'period': r['period'], 'tier': r['tier'],
                     't': r['created'], 'status': r['status'], 'note': r['note'], 'doneAt': r['decided'] or None} for r in self.db.q("SELECT id,user_id,plan_id,plan_name,period,amount,tier,created,status,note,decided FROM payments ORDER BY created DESC LIMIT 3000")]
        return [r['t'] for r in self.db.q("SELECT t FROM visits ORDER BY t DESC LIMIT 20000")]

    def adm_put(self, ctx, store, o):
        if not isinstance(o, dict): raise ApiError(400, 'bad')
        if store == 'settings':
            self.save_site(o); self.audit(ctx, ctx.admin['username'], 'settings'); return {'ok': True}
        oid = str(o.get('id', ''))
        if store == 'users':
            u = self.db.one("SELECT * FROM users WHERE id=?", (oid,))
            if not u: raise ApiError(404, 'no_user')
            sets, vals = [], []
            def S(col, v): sets.append(col + '=?'); vals.append(v)
            if 'name' in o: S('name', s_txt(o['name'], 30) or u['name'])
            if 'age' in o and o['age'] is not None: S('age', _int(o['age'], 18, 99, u['age']))
            if 'gender' in o: S('gender', o['gender'] if o['gender'] in ('m', 'f') else '')
            if 'city' in o: S('city', s_txt(o['city'], 40))
            if 'bio' in o: S('bio', s_txt(o['bio'], 600))
            if 'interests' in o and isinstance(o['interests'], list): S('interests', json.dumps([s_txt(x, 30) for x in o['interests'][:12] if isinstance(x, str)], ensure_ascii=False))
            if 'note' in o: S('note', s_txt(o['note'], 500))
            for k, col in (('verified', 'verified'), ('starred', 'starred'), ('premium', 'premium')):
                if k in o: S(col, 1 if o[k] is True else 0)
            if 'tier' in o:
                if o['tier'] not in ('regular', 'vip'): raise ApiError(400, 'bad_tier')
                S('tier', o['tier'])
            for k, col in (('groupAdmin', 'group_admin'), ('groupMuted', 'group_muted')):
                if k in o: S(col, 1 if o[k] is True else 0)
            if 'deleted' in o: S('deleted', 1 if o['deleted'] is True else 0)
            if 'status' in o:
                if o['status'] not in ('active', 'suspended', 'banned'): raise ApiError(400, 'bad_status')
                S('status', o['status'])
            for k, col, hi in (('premiumUntil', 'premium_until', now_ms() + 3650 * DAY), ('trialUntil', 'trial_until', now_ms() + 3650 * DAY)):
                if k in o:
                    v = _int(o[k], 0, hi, None)
                    if v is None: raise ApiError(400, 'bad_' + k)
                    S(col, v)
            for k, col in (('reports', 'reports'), ('views', 'views')):
                if k in o: S(col, _int(o[k], 0, 10 ** 9, 0))
            if 'email' in o:
                e = s_txt(o['email'], 80, False).lower()
                if e and not EMAIL_RE.match(e): raise ApiError(400, 'bad_email', {'msg': 'ایمیل نامعتبر'})
                S('email', e or None)
            if 'phone' in o:
                p = norm_phone(o['phone'])
                if p and not PHONE_RE.match(p): raise ApiError(400, 'bad_phone', {'msg': 'شماره نامعتبر'})
                S('phone', p or None)
            if 'profile' in o and isinstance(o['profile'], dict) and isinstance(o['profile'].get('photos'), list):
                prof = json.loads(u['profile'] or '{}'); prof['photos'] = [x for x in o['profile']['photos'] if img_ok(x)][:50]
                S('profile', json.dumps(prof, ensure_ascii=False))
            if sets:
                try: self.db.x("UPDATE users SET " + ','.join(sets) + " WHERE id=?", vals + [oid])
                except sqlite3.IntegrityError: raise ApiError(409, 'exists', {'msg': 'ایمیل یا شماره تکراری است'})
            if o.get('status') in ('suspended', 'banned') or o.get('deleted') is True:
                self.db.x("DELETE FROM sessions WHERE user_id=?", (oid,))
            self.audit(ctx, ctx.admin['username'], 'user_update', oid); return {'ok': True}
        if store == 'messages':
            self.db.x("UPDATE chatlog SET flagged=?,hidden=? WHERE id=?", (1 if o.get('flagged') is True else 0, 1 if o.get('hidden') is True else 0, oid)); return {'ok': True}
        if store == 'notifs':
            self.db.x("UPDATE notifs SET read=? WHERE id=?", (1 if o.get('read') is True else 0, oid)); return {'ok': True}
        if store == 'logs':
            if self.db.one("SELECT 1 FROM logs WHERE id=?", (oid,)): return {'ok': True}
            uid = o.get('userId') if isinstance(o.get('userId'), str) and UID_RE.match(o.get('userId')) else None
            lid = oid if re.match(r'^[A-Za-z0-9_-]{6,40}$', oid) else new_id()
            self.db.x("INSERT INTO logs(id,user_id,text,kind,t) VALUES(?,?,?,?,?)", (lid, uid if uid and self.db.one("SELECT 1 FROM users WHERE id=?", (uid,)) else None, s_txt(o.get('text'), 300, False), 'admin' if o.get('kind') == 'admin' else 'info', now_ms()))
            return {'ok': True}
        if store == 'support':
            r = self.db.one("SELECT * FROM support WHERE id=?", (oid,))
            if r:
                self.db.x("UPDATE support SET read=? WHERE id=?", (1 if o.get('read') is True else 0, oid)); return {'ok': True}
            th = str(o.get('userId', ''))
            if o.get('from') != 'a' or not (UID_RE.match(th) or re.match(r'^g[a-z0-9]{10,24}$', th)): raise ApiError(400, 'bad')
            text = s_txt(o.get('text'), 2000, False)
            if not text: raise ApiError(400, 'empty')
            self.db.x("INSERT INTO support(id,thread,sender,text,t,read) VALUES(?,?,'a',?,?,0)", (oid if re.match(r'^[A-Za-z0-9_-]{6,40}$', oid) else new_id(), th, text, now_ms())); return {'ok': True}
        if store == 'group':
            text = s_txt(o.get('text'), 500)
            if not text: raise ApiError(400, 'empty')
            if self.db.one("SELECT 1 FROM group_msgs WHERE id=?", (oid,)): return {'ok': True}
            self.db.x("INSERT INTO group_msgs(id,user_id,name,text,t,adm) VALUES(?,NULL,?,?,?,1)", (oid if re.match(r'^[A-Za-z0-9_-]{6,40}$', oid) else new_id(), s_txt(o.get('name'), 30) or 'LUMI Team', text, now_ms()))
            self.audit(ctx, ctx.admin['username'], 'group_post'); return {'ok': True}
        if store == 'payments': return {'ok': True}     # payments change ONLY through approve / reject
        raise ApiError(404, 'no_store')

    def adm_del(self, ctx, store, oid):
        t = {'users': 'users', 'messages': 'chatlog', 'notifs': 'notifs', 'logs': 'logs', 'support': 'support', 'group': 'group_msgs'}.get(store)
        if not t: raise ApiError(404, 'no_store')
        self.db.x("DELETE FROM %s WHERE id=?" % t, (oid,))
        self.audit(ctx, ctx.admin['username'], 'delete_' + store, oid); return {'ok': True}

    def pay_base(self, u, n): return max(n, u['premium_until'], u['trial_until'])
    def adm_pay(self, ctx, pid, action):
        a = ctx.admin['username']
        if action == 'delete':
            self.db.x("DELETE FROM payments WHERE id=?", (pid,)); self.audit(ctx, a, 'pay_delete', pid); return {'ok': True}
        if action == 'receipt':
            r = self.db.one("SELECT receipt FROM payments WHERE id=?", (pid,))
            if not r: raise ApiError(404, 'no_payment')
            return {'receipt': r['receipt']}
        if action not in ('approve', 'reject'): raise ApiError(404, 'bad_action')
        note = s_txt(ctx.body.get('note'), 140)
        if action == 'reject' and not note: raise ApiError(400, 'note_required', {'msg': 'دلیل رد را بنویسید'})
        with self.db.tx() as c:
            p = c.execute("SELECT * FROM payments WHERE id=?", (pid,)).fetchone()
            if not p: raise ApiError(404, 'no_payment')
            if p['status'] != 'pending': raise ApiError(409, 'not_pending', {'msg': 'این رسید قبلاً بررسی شده'})
            u = c.execute("SELECT * FROM users WHERE id=?", (p['user_id'],)).fetchone()
            if not u or u['deleted']: raise ApiError(404, 'no_user', {'msg': 'کاربر پیدا نشد'})
            n = now_ms()
            if action == 'approve':
                new = self.pay_base(u, n) + p['days'] * DAY
                tier = 'vip' if p['tier'] == 'vip' else ('vip' if self.is_vip(u) else 'regular')     # a regular renewal never downgrades an active VIP
                c.execute("UPDATE users SET premium=1,premium_until=?,tier=? WHERE id=?", (new, tier, u['id']))
                k = c.execute("UPDATE payments SET status='approved',decided=?,decided_by=?,new_premium_until=? WHERE id=? AND status='pending'", (n, a, new, pid)).rowcount
                msg = 'پرداخت شما تأیید شد و اشتراک «%s» فعال شد. ممنون از شما 💖' % p['plan_name']
            else:
                new = 0
                k = c.execute("UPDATE payments SET status='rejected',note=?,decided=?,decided_by=? WHERE id=? AND status='pending'", (note, n, a, pid)).rowcount
                msg = 'رسید شما تأیید نشد: %s — اگر پرداخت کرده‌اید، رسید واضح‌تری بفرستید.' % note
            if k != 1: raise ApiError(409, 'not_pending')
            c.execute("INSERT INTO support(id,thread,sender,text,t,read) VALUES(?,?,'a',?,?,0)", (new_id(), u['id'], msg, n))
            c.execute("INSERT INTO logs(id,user_id,text,kind,t) VALUES(?,?,?,?,?)", (new_id(), u['id'], ('پرداخت تأیید شد: ' if action == 'approve' else 'رسید پرداخت رد شد: ') + p['plan_name'], 'admin', n))
        self.audit(ctx, a, 'pay_' + action, pid)
        return {'ok': True, 'premiumUntil': new}

    def adm_user_action(self, ctx, uid, action):
        a = ctx.admin['username']
        u = self.db.one("SELECT * FROM users WHERE id=?", (uid,))
        if not u: raise ApiError(404, 'no_user')
        if action == 'extend':
            days = _int(ctx.body.get('days', 30), 1, 3650, 0)
            if not days: raise ApiError(400, 'bad_days')
            with self.db.tx() as c:
                u = c.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone()
                new = self.pay_base(u, now_ms()) + days * DAY
                c.execute("UPDATE users SET premium=1,premium_until=? WHERE id=?", (new, uid))
            self.log(uid, 'مدیر %d روز اشتراک اضافه کرد' % days, 'admin'); self.audit(ctx, a, 'extend', uid)
            return {'ok': True, 'premiumUntil': new}
        if action == 'reset-password':
            pw = ctx.body.get('password')
            if pw is None or pw == '': pw = secrets.token_urlsafe(9) + 'a1'
            if not pw_ok(pw): raise ApiError(400, 'weak_pw', {'msg': 'رمز: حداقل ۸ کاراکتر شامل حرف و عدد'})
            self.db.x("UPDATE users SET pw_hash=?,must_change=1 WHERE id=?", (hash_pw(pw), uid))
            self.db.x("DELETE FROM sessions WHERE user_id=?", (uid,))
            self.log(uid, 'رمز موقت توسط مدیر تنظیم شد', 'admin'); self.audit(ctx, a, 'reset_password', uid)
            return {'ok': True, 'password': pw}
        if action == 'logout-all':
            self.db.x("DELETE FROM sessions WHERE user_id=?", (uid,)); self.audit(ctx, a, 'logout_all', uid); return {'ok': True}
        raise ApiError(404, 'bad_action')
    def h_adm_user_add(self, ctx):
        """POST /api/admin/users admin 7000000"""
        b = ctx.body
        name = s_txt(b.get('name'), 30); email = s_txt(b.get('email'), 80, False).lower(); phone = norm_phone(b.get('phone'))
        if not name: raise ApiError(400, 'missing', {'msg': 'نام را وارد کنید'})
        if email and not EMAIL_RE.match(email): raise ApiError(400, 'bad_email', {'msg': 'ایمیل نامعتبر'})
        if phone and not PHONE_RE.match(phone): raise ApiError(400, 'bad_phone', {'msg': 'شماره نامعتبر'})
        pw = secrets.token_urlsafe(9) + 'a1'
        prof = {}
        if isinstance(b.get('photos'), list): prof['photos'] = [x for x in b['photos'] if img_ok(x)][:50]
        uid, uname = self.create_user(name, email, phone, pw, b.get('username') or name, prof)
        self.db.x("UPDATE users SET must_change=1,age=?,gender=?,city=?,bio=? WHERE id=?",
                  (_int(b.get('age'), 18, 99, None), 'm' if b.get('gender') == 'm' else 'f' if b.get('gender') == 'f' else '', s_txt(b.get('city'), 40), s_txt(b.get('bio'), 600), uid))
        self.audit(ctx, ctx.admin['username'], 'user_add', uid)
        return 200, {'id': uid, 'username': uname, 'password': pw}

    # ======================================================== dispatcher
    SEC_HEADERS = [
        ('X-Content-Type-Options', 'nosniff'), ('X-Frame-Options', 'DENY'), ('Referrer-Policy', 'no-referrer'),
        ('Cross-Origin-Opener-Policy', 'same-origin'), ('Cross-Origin-Resource-Policy', 'same-origin'),
        ('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=()'),
        ('Content-Security-Policy', "frame-ancestors 'none'; form-action 'self'; base-uri 'none'")]

    def ui_bytes(self):
        if self._ui is None:
            f = self.cfg.get('ui_file')
            if f: self._ui = open(f, 'rb').read()
            elif UI_B64.startswith('__'): self._ui = '<!doctype html><meta charset=utf-8><h1>UI not embedded in this build</h1>'.encode()
            else: self._ui = base64.b64decode(UI_B64)
        return self._ui

    def client_ip(self, peer, headers):
        if self.cfg['trust_proxy']:
            x = (headers.get('X-Forwarded-For') or '').split(',')[-1].strip()
            if re.match(r'^[0-9a-fA-F:.]{3,45}$', x): return x
        return peer

    def process(self, method, rawpath, headers, read_body, peer):
        """returns (status, [(header,value)...], body bytes)"""
        ctx = Ctx(); ctx.cookies = []; ctx.headers = headers; ctx.ip = self.client_ip(peer, headers); ctx.body = {}
        u = urllib.parse.urlsplit(rawpath[:2000]); path = u.path
        out_h = list(self.SEC_HEADERS)
        def reply(st, data, ctype='application/json; charset=utf-8', extra=None):
            body = data if isinstance(data, bytes) else json.dumps(data, ensure_ascii=False, separators=(',', ':')).encode()
            h = out_h + [('Content-Type', ctype), ('Cache-Control', 'no-store')]
            if self.cfg['secure']: h.append(('Strict-Transport-Security', 'max-age=31536000; includeSubDomains'))
            h += [('Set-Cookie', c) for c in ctx.cookies] + (extra or [])
            return st, h, body
        try:
            if method in ('GET', 'HEAD') and path in ('/', '/index.html'):
                return reply(200, self.ui_bytes(), 'text/html; charset=utf-8')
            if not path.startswith('/api/'): return reply(404, {'error': 'not_found'})
            if method not in ('GET', 'POST'): return reply(405, {'error': 'method'}, extra=[('Allow', 'GET, POST')])
            ctx.query = {k: v[0] for k, v in urllib.parse.parse_qs(u.query, max_num_fields=20).items()}
            if method == 'POST':
                ct = (headers.get('Content-Type') or '').split(';')[0].strip().lower()
                if ct != 'application/json': raise ApiError(415, 'content_type')
                org = headers.get('Origin'); host = headers.get('Host', '')
                if org:
                    if urllib.parse.urlsplit(org).netloc != host: raise ApiError(403, 'bad_origin')
                elif headers.get('Sec-Fetch-Site') not in (None, 'same-origin', 'none'): raise ApiError(403, 'bad_origin')
            self.load_session(ctx)
            fn = None; auth = 'anon'; maxb = 65536; args = ()
            r = self.routes.get((method, path))
            if r: fn, auth, maxb = r
            elif method == 'GET' and path == '/api/auth/google/callback':
                loc = self.google_callback(ctx)
                page = ('<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=%s"><title>LUMI</title>' % loc.replace('&', '&amp;').replace('"', '')).encode()
                return reply(200, page, 'text/html; charset=utf-8', [('Content-Security-Policy', "default-src 'none'")])
            else:
                for rx, meth, f, mb in self.adm_routes():
                    m = rx.match(path)
                    if m and meth == method: fn, auth, maxb, args = f, 'admin', mb, m.groups(); break
            if not fn: raise ApiError(404, 'not_found')
            if auth == 'user':
                if not ctx.user: raise ApiError(401, 'login_required', {'msg': 'Please sign in'})
                if method == 'POST': self.need_csrf(ctx)
                if ctx.user['must_change'] and path not in ('/api/password', '/api/session', '/api/logout'):
                    raise ApiError(403, 'password_change_required', {'msg': 'Please set a new password'})
            elif auth == 'admin':
                if not ctx.admin: raise ApiError(401, 'admin_required', {'msg': 'ورود مدیر لازم است'})
                if method == 'POST' and not hmac.compare_digest(headers.get('X-CSRF-Token', '') or '', ctx.asession['csrf']): raise ApiError(403, 'csrf')
            if method == 'POST':
                if headers.get('Transfer-Encoding'): raise ApiError(411, 'length_required')
                try: n = int(headers.get('Content-Length', ''))
                except ValueError: raise ApiError(411, 'length_required')
                if n < 0 or n > maxb: raise ApiError(413, 'too_large')
                raw = read_body(n)
                try: b = json.loads(raw.decode('utf-8')) if raw.strip() else {}
                except Exception: raise ApiError(400, 'bad_json')
                if not isinstance(b, dict): raise ApiError(400, 'bad_json')
                ctx.body = b
            res = fn(ctx, *args)
            st, data = res
            return reply(st, data)
        except ApiError as e:
            d = {'error': e.msg if not e.extra else e.msg}
            d = dict(e.extra); d['error'] = e.msg if isinstance(e.msg, str) and re.match(r'^[a-z_]+$', e.msg) else d.get('error', 'error')
            return reply(e.code, d)
        except Exception:
            traceback.print_exc()
            return reply(500, {'error': 'server_error', 'msg': 'Something went wrong'})

    def adm_routes(self):
        if not hasattr(self, '_adm'):
            def data(ctx, s): return 200, {'data': self.adm_data(ctx, s)}
            def put(ctx, s): return 200, self.adm_put(ctx, s, ctx.body)
            def dele(ctx, s, i): return 200, self.adm_del(ctx, s, i)
            def pay(ctx, i, a): return 200, self.adm_pay(ctx, i, a)
            def ua(ctx, i, a): return 200, self.adm_user_action(ctx, i, a)
            self._adm = [
                (re.compile(r'^/api/admin/data/([a-z]+)$'), 'GET', data, 1024),
                (re.compile(r'^/api/admin/put/([a-z]+)$'), 'POST', put, 7000000),
                (re.compile(r'^/api/admin/del/([a-z]+)/([A-Za-z0-9_\-]{1,40})$'), 'POST', dele, 1024),
                (re.compile(r'^/api/admin/pay/([A-Za-z0-9_\-]{1,40})/([a-z]+)$'), 'POST', pay, 4096),
                (re.compile(r'^/api/admin/users/(u[a-z0-9]{6,30})/([a-z\-]+)$'), 'POST', ua, 4096)]
        return self._adm

import random
def random_purge(): return random.random() < 0.02

class Handler(BaseHTTPRequestHandler):
    protocol_version = 'HTTP/1.1'
    timeout = 20
    server_version = 'LUMI'
    sys_version = ''
    def log_message(self, *a): pass
    def _go(self, method):
        app = self.server.app
        try:
            if len(self.requestline) > 2100: self.close_connection = True; return self.send_error(414)
            used = [False]
            def rb(n): used[0] = True; return self.rfile.read(n)
            st, hs, body = app.process(method, self.path, self.headers, rb, self.client_address[0])
            self.send_response(st)
            for k, v in hs: self.send_header(k, v)
            if method == 'POST' and not used[0]:
                self.send_header('Connection', 'close'); self.close_connection = True      # unread body must not be parsed as the next request
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            if method != 'HEAD': self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError, socket.timeout): self.close_connection = True
    def do_GET(self): self._go('GET')
    def do_HEAD(self): self._go('HEAD')
    def do_POST(self): self._go('POST')
    def do_PUT(self): self._go('PUT')
    def do_DELETE(self): self._go('DELETE')
    def do_PATCH(self): self._go('PATCH')
    def do_OPTIONS(self): self._go('OPTIONS')

class Server(ThreadingHTTPServer):
    daemon_threads = True
    request_queue_size = 64
    def __init__(self, addr, app):
        self.app = app; self.sem = threading.BoundedSemaphore(128)
        super().__init__(addr, Handler)
    def handle_error(self, request, client_address): pass
    def process_request(self, request, client_address):
        if not self.sem.acquire(blocking=False): self.shutdown_request(request); return
        super().process_request(request, client_address)
    def process_request_thread(self, request, client_address):
        try: super().process_request_thread(request, client_address)
        finally: self.sem.release()

def make_server(cfg):
    app = App(cfg)
    srv = Server((cfg['host'], cfg['port']), app)
    if cfg['tls_cert'] and cfg['tls_key']:
        ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER); ctx.minimum_version = ssl.TLSVersion.TLSv1_2
        ctx.load_cert_chain(cfg['tls_cert'], cfg['tls_key']); srv.socket = ctx.wrap_socket(srv.socket, server_side=True)
    if cfg['tg_token']: threading.Thread(target=app.tg_loop, daemon=True).start()
    return srv

def cmd_create_admin(cfg):
    un = os.environ.get('LUMI_ADMIN_USER') or input('Admin username: ').strip().lower()
    pw = os.environ.get('LUMI_ADMIN_PASS') or getpass.getpass('Admin password (10+ chars, letters + digits): ')
    if not re.match(r'^[a-z0-9_.-]{3,40}$', un): sys.exit('Username: 3-40 chars a-z 0-9 _ . -')
    if not pw_ok(pw) or len(pw) < 10: sys.exit('Password must be 10+ characters with a letter and a number')
    if not os.environ.get('LUMI_ADMIN_PASS') and getpass.getpass('Repeat password: ') != pw: sys.exit('Passwords do not match')
    db = DB(cfg['db'])
    db.x("INSERT INTO admins(username,pw_hash,created) VALUES(?,?,?) ON CONFLICT(username) DO UPDATE SET pw_hash=excluded.pw_hash", (un, hash_pw(pw), now_ms()))
    db.x("DELETE FROM admin_sessions WHERE admin_id=(SELECT id FROM admins WHERE username=?)", (un,))
    print('Admin "%s" saved. Open the app, hold the logo for 5 seconds, and sign in.' % un)

def main(argv):
    cfg = load_config()
    cmd = argv[1] if len(argv) > 1 else 'run'
    if cmd == 'create-admin': return cmd_create_admin(cfg)
    if cmd == 'export-ui':
        out = argv[2] if len(argv) > 2 else 'index.html'
        if UI_B64.startswith('__'): sys.exit('UI not embedded in this build')
        open(out, 'wb').write(base64.b64decode(UI_B64)); print('written', out); return
    if cmd != 'run': sys.exit(__doc__)
    srv = make_server(cfg)
    if not srv.app.db.one("SELECT 1 FROM admins"): print('!! No admin yet — run:  python3 lumi_server.py create-admin')
    if cfg['host'] not in ('127.0.0.1', 'localhost', '::1') and not cfg['secure']:
        print('!! Listening on a public address without HTTPS. Put it behind HTTPS (Caddy/nginx/cloudflared) or set LUMI_TLS_CERT/KEY.')
    print('LUMI running on %s://%s:%d  (db: %s)' % ('https' if cfg['secure'] else 'http', cfg['host'], cfg['port'], cfg['db']))
    try: srv.serve_forever()
    except KeyboardInterrupt: pass

if __name__ == '__main__':
    main(sys.argv)
